"""Generate authenticated fixed U2 boot, scaling/FFT and queued-command blocks; no runtime decoder."""
from pathlib import Path
import argparse
import hashlib
import json

ROOT = Path(__file__).resolve().parents[2]
U2_SHA256 = "82bdcbbd9413071f20a52cf7fd0fcf094fa474a08938b4f8c1d617d1490a137c"
# generated by the setup (tools/setup/paths.py output('mk2')); computed here so the module also loads as a plain file
OUTPUT = ROOT / 'generated/mk2' / json.loads((ROOT / 'tools/mk2/roms-l31.json').read_text(encoding='utf-8'))['program_sha256'] / 'mk2_adsp_boot.inc'


REG0 = ["ax0", "ax1", "mx0", "mx1", "ay0", "ay1", "my0", "my1",
        "si", "se", "ar", "mr0", "mr1", "mr2", "sr0", "sr1"]
# U2 locators (addresses only) for the opcode sets and fixed words; the words themselves are read from the
# user's U2 by load_u2() and accepted only when their SHA-256 matches (tools/mk2/adsp_opcode_sets.json).
SETS = json.loads(Path(__file__).with_name('adsp_opcode_sets.json').read_text(encoding='utf-8'))


def _runs(name):
    return tuple(pc for first, last in SETS['pc_runs'][name] for pc in range(first, last + 1))


def _path(name):
    manifest = json.loads(Path(__file__).with_name(name).read_text(encoding='utf-8'))
    return tuple(int(pc, 16) for pc in manifest['pcs']), manifest['words_sha256']


def _digest(values):
    """SHA-256 of the words as 8-byte little-endian integers (tools/mk2/oracle_digest.py serialization)."""
    return hashlib.sha256(b''.join(int(value).to_bytes(8, 'little') for value in values)).hexdigest()


# Second-boot loader image and its original init code.
NEW_PCS = (0, *range(8, 0x25), *range(0x3e8, 0x3f6), *range(0x800, 0x8ae))
# Executed unchanged-input firmware after the bank-two DM clear.
IDLE_PCS = _runs('IDLE_PCS')
HANDSHAKE_PCS = _runs('HANDSHAKE_PCS')
RESUME_PCS = _runs('RESUME_PCS')
SELFTEST_PCS, SELFTEST_SHA256 = _path('valid_boot_dsp_path.json')


def dag_write(register, index, expression):
    if index == 0:
        setter = "WriteIndex0" if register == "i" else "WriteLength0"
        return f"{setter}({expression});"
    return f"{register}[{index}] = {expression};"


def new_translation(op):
    if op not in NEW_OPS | NEW_EXTRA_OPS:
        raise ValueError(f"Unsupported ADSP boot opcode {op:06x}")
    top = op >> 16
    reg = op & 15
    value = (op >> 4) & 0x3fff
    if op == 0x930008:
        return "WriteData(0x3000, si);"
    if op in (0x1c3e8f, 0x1c800f, 0x1c897f):
        return f"PushPc(); pc = 0x{value:04x};"
    if op == 0x0a000f:
        return "ReturnCall();"
    if op == 0x18008f:
        return "pc = 0x0008;"
    if op == 0x0d0c50:
        return "SetCounter(ax0);"
    if op == 0x0d0c51:
        return "SetCounter(ax1);"
    if op == 0x0d0c70:
        return "px = uint8_t(ax0);"
    if op == 0x0d0cb0:
        return "SportTransmit(ax0);"
    if op == 0x0d040a:
        return dag_write("i", 0, "ar & 0x3fff")
    if op == 0x0d047e:
        return "m[3] = int16_t((sr0 & 0x2000) ? (sr0 | 0xc000) : (sr0 & 0x3fff));"
    if op == 0x090003:
        return "Modify(0, 3);"
    if op == 0x3c03fc:
        return "SetIfc(0x003f);"
    if op >> 20 == 4:
        if reg in (9, 13):
            return f"{REG0[reg]} = uint16_t(int16_t(int8_t(0x{(op >> 4) & 0xff:02x})));"
        return f"{REG0[reg]} = 0x{(op >> 4) & 0xffff:04x};"
    group = op >> 18
    if group in (13, 14) and reg < 12:
        index = (reg & 3) + (4 if group == 14 else 0)
        if reg < 4:
            return dag_write("i", index, f"0x{value:04x}")
        if reg < 8:
            signed = value - 0x4000 if value & 0x2000 else value
            return f"m[{index}] = {signed};"
        return dag_write("l", index, f"0x{value:04x}")
    if group == 15:
        if reg == 5:
            return f"SetCounter(0x{value:04x});"
        if reg in (3, 4):
            return f"SetInterruptControl({reg}, 0x{value:04x});"
    if group == 5 and reg == 14:
        return f"StartLoop(0x{value:04x});"
    if 0x80 <= top <= 0x83:
        return f"{REG0[reg]} = ReadData(0x{value:04x});"
    if 0x90 <= top <= 0x93:
        return f"WriteData(0x{value:04x}, {REG0[reg]});"
    if top == 0xa0:
        return f"WriteDag({(op >> 2) & 3}, {op & 3}, 0x{(op >> 4) & 0xffff:04x});"
    if top in (0x60, 0x70, 0x68, 0x78):
        index = ((op >> 2) & 3) + (4 if top & 0x10 else 0)
        modifier = (op & 3) + (4 if top & 0x10 else 0)
        if (op >> 13) & 15:
            raise ValueError("Unqualified MAC operation")
        register = REG0[(op >> 4) & 15]
        if top & 8:
            return f"WriteDag({index}, {modifier}, {register});"
        return f"{register} = ReadDag({index}, {modifier});"
    if op == 0x5800e1:
        return "WriteProgramDag(4, 5, sr0);"
    if op == 0x5800b1:
        return "WriteProgramDag(4, 5, mr0);"
    if op == 0x1210a1:
        return "ShiftSi(); ar = ReadDag(0, 1);"
    if op == 0x638202:
        return "LogicAr(uint16_t(ar & ay0)); ax0 = ReadDag(0, 2);"
    if op == 0x226a0f:
        return "AddAr(ar, ay1);"
    if op == 0x23820f:
        return "LogicAr(uint16_t(ar & ay0));"
    if op == 0x0f1a00:
        return "SetShift((uint32_t(sr1) << 16) | sr0 | ar);"
    if op == 0x0f1008:
        return "SetShift(uint32_t(si) << 8);"
    if op == 0x0f1208:
        return "SetShift(uint32_t(ar) << 8);"
    raise ValueError(f"Unsupported ADSP second-boot opcode {op:06x}")


def translate(op, *, batch_forms=False):
    _ensure()
    exact = {0x18022f: "pc = 0x0022;", 0x5000a5: "ReadProgramAr();",
             0x5800a2: "WriteProgramAr();", 0x700080: "si = ReadInput();",
             0x0d0c18: "SetMstat();", 0x839fca: "ar = ReadData(0x39fc);",
             0x267a0f: "CopyArToAf();", 0x180f41: "DelayBranch();", 0: "",
             0x1816ef: "pc = 0x016e;", 0x0c0030: "SelectBank(uint8_t(mstat | 1));",
             0x0d0337: "mx1 = px;", 0x0d0220: "mx0 = i[4];",
             0x83400a: "ar = ReadInput();", 0x979fc5: "WriteData(0x39fc, uint16_t(m[5]));",
             0x0d0c73: "px = uint8_t(mx1);", 0x0d0802: "i[4] = mx0 & 0x3fff;",
             0x0a001f: "ReturnIrq();"}
    if op in exact:
        return exact[op]
    group, reg, value = op >> 18, op & 15, (op >> 4) & 0x3fff
    if op >> 20 == 4 and reg == 8:
        return f"si = 0x{(op >> 4) & 0xffff:04x};"
    if group in (13, 14) and reg < 12:
        index = (reg & 3) + (4 if group == 14 else 0)
        if reg < 4:
            return dag_write("i", index, f"0x{value:04x}")
        if reg < 8:
            signed = value - 0x4000 if value & 0x2000 else value
            return f"m[{index}] = {signed};"
        if value == 0:
            return dag_write("l", index, "0")
    if group == 15:
        if reg == 5:
            return f"SetCounter(0x{value:04x});"
        if reg in (3, 4) and value in (0, 0x20):
            return f"SetInterruptControl({reg}, 0x{value:04x});"
    if op >> 18 == 5 and reg == 14:
        return f"StartLoop(0x{value:04x});"
    if op >> 16 == 0x93 and reg == 8 and value in (0x3ffe, 0x3fff):
        return f"WriteControl(0x{value:04x}, si);"
    if op >> 16 == 0x97 and reg == 4 and value in (0x39fb, 0x39fc):
        return f"WriteData(0x{value:04x}, uint16_t(m[0]));"
    try:
        return new_translation(op)
    except ValueError:
        return idle_translation(op, batch_forms=batch_forms)


# Independently reached after the eleventh original SPORT callback; U2 words
# match both PM snapshots and no observed DM alias write targets these PCs.
PALETTE_PCS = (0x998, 0x999, 0x99a, 0x99b, 0x99c, 0x99d, 0x99e)
PAIR_PCS, PAIR_SHA256 = _path('coin_pair_dsp_path.json')
RELEASE_PCS, RELEASE_SHA256 = _path('start_release_dsp_path.json')
SELECTION_PCS, SELECTION_SHA256 = _path('selection_dsp_path.json')
FIGHT_PCS, FIGHT_SHA256 = _path('first_fight_dsp_path.json')
BRANCH_PCS, BRANCH_SHA256 = _path('dsp_branch_closure.json')
# Original neutral firmware wraps its sample pointer at DSP cycle759405591: six ROM-qualified PCs, including RETS.
# Fresh Original neutral branch at DSP879136480. Actual late PM in an Original finisher scene (both clamp branches).
# Captured fight: nonzero queued-command countdown at TMS cycle789284896.
FIXED = {name: (tuple(row['pcs']), row['sha256']) for name, row in SETS['words'].items()}
# Every U2-derived name below is set by load_u2(); `generate()` passes its U2, other callers get the local one.
DERIVED = ('NEW_OPS', 'NEW_EXTRA_OPS', 'IDLE_OPS', 'HANDSHAKE_OPS', 'RESUME_OPS', 'PALETTE_OPS', 'BATCH_OPS',
           'SELFTEST_WORDS', 'SELFTEST_OPS', 'PAIR_WORDS', 'PAIR_OPS', 'RELEASE_WORDS', 'RELEASE_OPS',
           'SELECTION_WORDS', 'SELECTION_OPS', 'FIGHT_WORDS', 'FIGHT_OPS', 'BRANCH_WORDS', *FIXED)
_loaded = None


def load_u2(data):
    """Derive the opcode sets and fixed words from the authenticated U2; each must match its SHA-256."""
    global _loaded
    if len(data) != 0x80000 or hashlib.sha256(data).hexdigest() != U2_SHA256:
        raise ValueError("Generation requires authenticated MK2 L3.1 U2")
    word = lambda offset: int.from_bytes(data[offset:offset+3], "big")
    firmware = lambda pc: word(0x1000 + pc * 4 if pc < 0x400 else 0x2000 + (pc - 0x800) * 4)
    loader = lambda pc: word(0x1000 + pc * 4 if pc < 0x400 else 0x800 + (pc - 0x800) * 4)
    values = {}
    def ops(name, words):
        values[name] = set(words)
        if _digest(sorted(values[name])) != SETS['sets'][name]['sha256']:
            raise ValueError(f"ADSP {name} differs from authenticated U2")
    def fixed(name, pcs, read, digest, message):
        values[name] = {pc: read(pc) for pc in pcs}
        if _digest(values[name].values()) != digest:
            raise ValueError(message)
    ops('NEW_OPS', map(loader, NEW_PCS))
    ops('IDLE_OPS', map(firmware, IDLE_PCS))
    for name in ('NEW_EXTRA_OPS', 'HANDSHAKE_OPS', 'RESUME_OPS', 'PALETTE_OPS', 'BATCH_OPS'):
        ops(name, map(word, SETS['sets'][name]['u2_offsets']))
    fixed('SELFTEST_WORDS', SELFTEST_PCS, lambda pc: word(pc * 4), SELFTEST_SHA256,
          "Valid-boot self-test DSP word differs from authenticated U2")
    for name, pcs, digest, message in (
            ('PAIR_WORDS', PAIR_PCS, PAIR_SHA256, "Coin pair DSP word differs from authenticated U2"),
            ('RELEASE_WORDS', RELEASE_PCS, RELEASE_SHA256, "Start release DSP word differs from authenticated U2"),
            ('SELECTION_WORDS', SELECTION_PCS, SELECTION_SHA256, "Selection DSP word differs from authenticated U2"),
            ('FIGHT_WORDS', FIGHT_PCS, FIGHT_SHA256, "First-fight DSP word differs from authenticated U2"),
            ('BRANCH_WORDS', BRANCH_PCS, BRANCH_SHA256, "Direct DSP branch word differs from authenticated U2"),
            *((name, *FIXED[name], f"ADSP {name} differ from authenticated U2") for name in FIXED)):
        fixed(name, pcs, firmware, digest, message)
    for name in ('SELFTEST', 'PAIR', 'RELEASE', 'SELECTION', 'FIGHT'):
        values[name + '_OPS'] = set(values[name + '_WORDS'].values())
    globals().update(values)
    _loaded = hashlib.sha256(data).hexdigest()


def _ensure():
    if _loaded is None:
        load_u2((ROOT / "roms/mk2/su2.l1").read_bytes())


def __getattr__(name):
    if name in DERIVED:
        _ensure()
        return globals()[name]
    raise AttributeError(name)


def idle_translation(op, *, batch_forms=False):
    top, reg, value = op >> 16, op & 15, (op >> 4) & 0x3fff
    condition = {0: "astat & 1", 1: "!(astat & 1)",
                 2: "!(astat & 1) && !((astat ^ (astat >> 1)) & 2)",
                 3: "(astat & 1) || ((astat ^ (astat >> 1)) & 2)",
                 4: "(astat ^ (astat >> 1)) & 2", 5: "!((astat ^ (astat >> 1)) & 2)",
                 10: "astat & 0x10", 15: "true"}
    supported_form = batch_forms and (op in BATCH_OPS or 0x40 <= top <= 0x4f or
                                      0x80 <= top <= 0x83 or (0x18 <= top <= 0x1f and reg in condition))
    if not supported_form and op not in IDLE_OPS | HANDSHAKE_OPS | RESUME_OPS | PALETTE_OPS | PAIR_OPS | RELEASE_OPS | SELECTION_OPS | FIGHT_OPS | SELFTEST_OPS | set(FINISH_CLAMP_WORDS.values()) | set(BRANCH_WORDS.values()):
        raise ValueError(f"Unsupported ADSP idle opcode {op:06x}")
    if op == 0x061000:
        return "DivideSign();"
    if op == 0x071000:
        return "DivideQuotient();"

    def guarded(statement):
        return statement if reg == 15 else f"if ({condition[reg]}) {statement}"

    def read(group, number):
        if group == 0:
            return REG0[number]
        if group in (1, 2) and number < 12:
            index = (number & 3) + (4 if group == 2 else 0)
            return f"{'i' if number < 4 else 'm' if number < 8 else 'l'}[{index}]"
        if group == 3 and number == 7:
            return "uint16_t(px)"
        if group == 3 and number == 5:
            return "cntr"
        raise ValueError(f"Unqualified read group {group} register {number}")

    def write(group, number, expression):
        if group == 0:
            if number == 12:
                return f"mr1 = {expression}; mr2 = (mr1 & 0x8000) ? 0xffff : 0;"
            if number in (9, 13):
                expression = f"uint16_t(int16_t(int8_t({expression})))"
            return f"{REG0[number]} = {expression};"
        if group in (1, 2) and number < 12:
            index = (number & 3) + (4 if group == 2 else 0)
            if number < 4:
                return dag_write("i", index, f"({expression}) & 0x3fff")
            if number < 8:
                return f"m[{index}] = SignedModifier({expression});"
            return dag_write("l", index, f"({expression}) & 0x3fff")
        if group == 3:
            if number == 1:
                return f"SelectBank(uint8_t({expression}));"
            if number == 5:
                return f"SetCounter({expression});"
            if number == 7:
                return f"px = uint8_t({expression});"
            if number == 13:
                return f"cntr = ({expression}) & 0x3fff;"
        raise ValueError(f"Unqualified write group {group} register {number}")

    def alu(destination):
        x = ["ax0", "ax1", "ar", "mr0", "mr1", "mr2", "sr0", "sr1"][(op >> 8) & 7]
        y = ["ay0", "ay1", "af", "uint16_t(0)"][(op >> 11) & 3]
        function = (op >> 13) & 15
        saturate = "true" if destination == "ar" else "false"
        expressions = {0: f"Logic({y})", 1: f"Increment({y}, {saturate})",
                       3: f"Add({x}, {y}, {saturate})", 5: f"Negate({y}, {saturate})",
                       7: f"Sub({x}, {y}, {saturate})", 8: f"Decrement({y}, {saturate})",
                       9: f"Sub({y}, {x}, {saturate})", 12: f"Logic(uint16_t({x} & {y}))",
                       11: f"Logic(uint16_t(~{x}))",
                       13: f"Logic(uint16_t({x} | {y}))", 14: f"Logic(uint16_t({x} ^ {y}))",
                       15: f"Absolute({x}, {saturate})"}
        return f"{destination} = {expressions[function]};"

    def mac():
        function = (op >> 13) & 15
        if not function:
            return ""
        x = ["mx0", "mx1", "ar", "mr0", "mr1", "mr2", "sr0", "sr1"][(op >> 8) & 7]
        y = ["my0", "my1", "mf", "uint16_t(0)"][(op >> 11) & 3]
        signed = (0 if function < 4 else function & 3)
        action = function if function < 4 else (function >> 2)
        return (f"MacMr({x}, {y}, {'false' if signed & 2 else 'true'}, "
                f"{'false' if signed & 1 else 'true'}, {action}, {'true' if function < 4 else 'false'});")

    if top == 0:
        return ""
    if top == 5:
        return "SaturateMr();"
    if top == 9:
        index, modifier = (op >> 2) & 7, (op & 3) | ((op >> 2) & 4)
        return f"Modify({index}, {modifier});"
    if top == 0x0a:
        return guarded("ReturnCall();")
    if top == 0x0b:
        return guarded(f"pc = i[{4 + ((op >> 6) & 3)}] & 0x3fff;")
    if top == 0x0c:
        if op == 0x0c00c0:
            return "SelectBank(uint8_t(mstat | 2));"
        if op == 0x0c0080:
            return "SelectBank(uint8_t(mstat & ~2));"
        if op == 0x0c2000:
            return "SelectBank(uint8_t(mstat & ~0x10));"
        if op == 0x0c3000:
            return "SelectBank(uint8_t(mstat | 0x10));"
        raise ValueError(f"Unqualified mode change {op:06x}")
    if top == 0x0d:
        group = (op >> 8) & 15
        return write(group >> 2, (op >> 4) & 15, read(group & 3, reg))
    if top in (0x0e, 0x0f, 0x10, 0x12):
        source = ["si", "si", "ar", "mr0", "mr1", "mr2", "sr0", "sr1"][(op >> 8) & 7]
        function = (op >> 11) & 15
        if function == 12 and top == 0x0e:
            return guarded(f"Exponent({source});")
        if function == 6 and top in (0x0e, 0x0f):
            count = str((op & 255) - (256 if op & 128 else 0)) if top == 0x0f else "int8_t(se)"
            statement = f"ShiftArithmetic({source}, {count});"
            return statement if top == 0x0f else guarded(statement)
        if function > 3:
            raise ValueError(f"Unqualified shift {op:06x}")
        count = str((op & 255) - (256 if op & 128 else 0)) if top == 0x0f else "int8_t(se)"
        statement = f"ShiftLogical({source}, {count}, {'true' if function < 2 else 'false'}, {'true' if function & 1 else 'false'});"
        if top == 0x10:
            return statement + " " + write(0, (op >> 4) & 15, read(0, reg))
        if top == 0x12:
            index, modifier, register = (op >> 2) & 3, op & 3, (op >> 4) & 15
            if op & 0x8000:
                return f"WriteDag({index}, {modifier}, {REG0[register]}); " + statement
            return statement + " " + write(0, register, f"ReadDag({index}, {modifier})")
        return statement if top == 0x0f else guarded(statement)
    if 0x14 <= top <= 0x17:
        if reg != 14:
            raise ValueError("Unqualified non-counter loop")
        return f"StartLoop(0x{value:04x});"
    if 0x18 <= top <= 0x1b:
        return guarded(f"pc = 0x{value:04x};")
    if 0x1c <= top <= 0x1f:
        return guarded(f"{{ PushPc(); pc = 0x{value:04x}; }}")
    if top in (0x20, 0x21):
        return guarded(mac())
    if top in (0x22, 0x23, 0x26, 0x27):
        return guarded(alu("af" if top & 4 else "ar"))
    if top in (0x28, 0x29, 0x2a, 0x2b, 0x2e, 0x2f):
        return "{ const auto moved = " + read(0, reg) + "; " + (alu("af" if top & 4 else "ar") if top & 2 else mac()) + " " + write(0, (op >> 4) & 15, "moved") + " }"
    if 0x34 <= top <= 0x3f:
        return write((top - 0x30) >> 2, reg, f"0x{value:04x}")
    if 0x40 <= top <= 0x4f:
        return write(0, reg, f"0x{(op >> 4) & 0xffff:04x}")
    if top in (0x50, 0x58):
        index, modifier = 4 + ((op >> 2) & 3), 4 + (op & 3)
        register = (op >> 4) & 15
        if (op >> 13) & 15:
            raise ValueError(f"Unqualified parallel PM arithmetic {op:06x}")
        if top == 0x58:
            return f"WriteProgramDag({index}, {modifier}, {read(0, register)});"
        return write(0, register, f"ReadProgramDag({index}, {modifier})")
    if 0x60 <= top <= 0x7f:
        index = ((op >> 2) & 3) + (4 if top & 0x10 else 0)
        modifier = (op & 3) + (4 if top & 0x10 else 0)
        if (top & 6) == 4:
            raise ValueError(f"Unqualified parallel MAC-to-MF {op:06x}")
        arithmetic = alu("af" if top & 4 else "ar") if top & 2 else mac()
        if top & 8:
            return f"WriteDag({index}, {modifier}, {REG0[(op >> 4) & 15]}); {arithmetic}".rstrip()
        return arithmetic + " " + write(0, (op >> 4) & 15, f"ReadDag({index}, {modifier})")
    if 0x80 <= top <= 0x8f:
        return write((top - 0x80) >> 2, reg, f"ReadData(0x{value:04x})")
    if 0x90 <= top <= 0x9f:
        return f"WriteData(0x{value:04x}, {read((top - 0x90) >> 2, reg)});"
    if 0xa0 <= top <= 0xaf:
        return f"WriteDag({(op >> 2) & 3}, {op & 3}, 0x{(op >> 4) & 0xffff:04x});"
    raise ValueError(f"Unsupported ADSP idle opcode {op:06x}")


def generate(data):
    load_u2(data)
    words = [int.from_bytes(data[n:n+3], "big") for n in range(0, (data[3]+1)*32, 4)]
    lines = ["// Generated by tools/mk2/generate_adsp.py; do not edit.",
             "// U2 SHA-256: " + U2_SHA256,
             "// Semantics: pinned MAME adsp2100.cpp / 2100ops.hxx (BSD-3-Clause, Aaron Giles)."]
    old_pcs = [0, 4, *range(0x22, 0x49), *range(0xf4, 0xf9), *range(0x16e, 0x177)]
    for pc in old_pcs:
        op = words[0x1c if pc == 4 else pc]
        guard = " CheckSoftwareBoot();" if pc == 0xf8 else ""
        lines.append(f"case 0x{pc:05x}: CheckOpcode(0x{op:06x});{guard} Advance(); {translate(op)} break;")
    for pc,op in SELFTEST_WORDS.items():
        if pc in old_pcs or words[pc]!=op:
            raise ValueError(f"Valid-boot self-test DSP word differs from authenticated U2 at {pc:04x}")
        lines.append(f"case 0x{pc:05x}: CheckOpcode(0x{op:06x}); Advance(); {translate(op)} break;")
    new_pcs = NEW_PCS
    for pc in new_pcs:
        # Original loader reads four U2 bytes per PM word; the fourth becomes PX.
        offset = 0x1000 + pc * 4 if pc < 0x400 else 0x800 + (pc - 0x800) * 4
        op = int.from_bytes(data[offset:offset+3], "big")
        lines.append(f"case 0x{pc | 0x10000:05x}: CheckOpcode(0x{op:06x}); Advance(); {translate(op)} break;")
    for pc in dict.fromkeys((*IDLE_PCS, *HANDSHAKE_PCS, *RESUME_PCS, *PALETTE_PCS, *PAIR_PCS, *RELEASE_PCS, *SELECTION_PCS, *FIGHT_PCS, *NEUTRAL_WRAP_WORDS, *NEUTRAL_CLEAR_WORDS, *FINISH_CLAMP_WORDS, *COMMAND_COUNTDOWN_WORDS, *BRANCH_WORDS)):
        offset = 0x1000 + pc * 4 if pc < 0x400 else 0x2000 + (pc - 0x800) * 4
        op = int.from_bytes(data[offset:offset+3], "big")
        # Words at these PCs are authenticated by load_u2() (SHA-256 of the U2 words).
        block = f"CheckOpcode(0x{op:06x}); Advance(); {translate(op)} break;"
        if pc in new_pcs:
            original = next(n for n, line in enumerate(lines) if line.startswith(f"case 0x{pc | 0x10000:05x}:"))
            if f"CheckOpcode(0x{op:06x})" in lines[original]:
                continue
            lines[original] = f"case 0x{pc | 0x10000:05x}: if (ReadProgram(pc) == 0x{op:06x}) {{ {block} }} " + lines[original].split(": ", 1)[1]
        else:
            lines.append(f"case 0x{pc | 0x10000:05x}: {block}")
    return "\n".join(lines) + "\n"


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--check", action="store_true")
    parser.add_argument("--u2", type=Path, default=ROOT / "roms/mk2/su2.l1")
    args = parser.parse_args()
    text = generate(args.u2.read_bytes())
    if args.check:
        if OUTPUT.read_text(encoding="utf-8") != text:
            raise ValueError("ADSP generated source is stale")
    else:
        OUTPUT.write_text(text, encoding="utf-8", newline="\n")
    count = text.count("CheckOpcode(")
    print(f"ADSP: {count} fixed native instruction blocks " + ("verified" if args.check else "generated"))


if __name__ == "__main__":
    main()
